const envelope=JSON.parse(JSON.stringify($node['Sub-workflow Input'].json));
const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length&&r._id);
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const normalizePhone=v=>{const digits=String(v??'').replace(/\D/g,'');if(digits.length===11&&digits.startsWith('1'))return digits.slice(1);return digits.length===10?digits:null;};
const resolution=envelope.context.resolution??(envelope.context.resolution={});
const warnings=resolution.warnings??(resolution.warnings=[]);
const upstream=envelope.context.dealer??{};
const dealerId=id(envelope.identity.dealer_id);
const dealer=dealerId?(rows.find(r=>id(r._id)===dealerId)??null):null;
if(dealerId&&!dealer&&!warnings.includes('DEALER_CONFIGURATION_NOT_FOUND'))warnings.push('DEALER_CONFIGURATION_NOT_FOUND');
const d=dealer?.dealer_account_information??{};
const configuredPhone=d.sms_conversion_phone??null;
const incomingPhone=envelope.event.recipient??null;
const configuredNormalized=normalizePhone(configuredPhone);
const incomingNormalized=normalizePhone(incomingPhone);
if(dealer&&configuredNormalized&&incomingNormalized&&configuredNormalized!==incomingNormalized&&!warnings.includes('DEALER_CONFIGURATION_PHONE_MISMATCH'))warnings.push('DEALER_CONFIGURATION_PHONE_MISMATCH');
const addressParts=[d.store_address,d.store_city,d.store_state,d.store_postal,d.store_country].filter(Boolean);
const configuredAddress=addressParts.length?addressParts.join(', '):(d.address??null);
const dayNames={monday:'Monday',tuesday:'Tuesday',wednesday:'Wednesday',thursday:'Thursday',friday:'Friday',saturday:'Saturday',sunday:'Sunday'};
const canonicalDay=value=>{const raw=String(value??'').trim();return dayNames[raw.toLowerCase()]??raw;};
const normalizeHours=(value,requireActive)=>{
  const entries=Array.isArray(value)?value.map(v=>[v?.day??v?.name??'',v]):value&&typeof value==='object'?Object.entries(value):[];
  return entries.filter(([,v])=>v&&typeof v==='object'&&(requireActive?v.active===true:v.active!==false)).map(([key,v])=>({day:canonicalDay(v.day??v.name??key),start:String(v.start??v.open??'').trim(),end:String(v.end??v.close??'').trim()})).filter(v=>v.day&&v.start&&v.end);
};
const weekly=d.weekly_availability&&typeof d.weekly_availability==='object'&&!Array.isArray(d.weekly_availability)?d.weekly_availability:null;
const hasWeekly=!!weekly&&Object.keys(weekly).length>0;
const upstreamHoursRaw=upstream.store_hours??null;
const derivedHours=hasWeekly?normalizeHours(weekly,true):[];
const fallbackHours=hasWeekly?[]:normalizeHours(upstreamHoursRaw,!Array.isArray(upstreamHoursRaw));
const storeHours=hasWeekly?derivedHours:fallbackHours;
if(!hasWeekly&&upstreamHoursRaw!==null&&storeHours.length===0&&!(Array.isArray(upstreamHoursRaw)&&upstreamHoursRaw.length===0)&&!warnings.includes('MALFORMED_UPSTREAM_STORE_HOURS'))warnings.push('MALFORMED_UPSTREAM_STORE_HOURS');
const derivedHoursText=derivedHours.length?derivedHours.map(h=>h.day+': '+h.start+'–'+h.end).join(', '):null;
const upstreamHoursText=upstream.store_hours_text??null;
const storeHoursText=hasWeekly?derivedHoursText:(upstreamHoursText??null);
const storeHoursStatus=hasWeekly?(derivedHours.length?'CONFIGURED':'CONFIGURED_NO_ACTIVE_HOURS'):(upstreamHoursRaw!==null||upstreamHoursText!==null?(storeHours.length||Array.isArray(upstreamHoursRaw)&&upstreamHoursRaw.length===0?'UPSTREAM_FALLBACK':'UPSTREAM_MALFORMED'):'UNAVAILABLE');
const bookingUrl=d.booking_url??upstream.booking_url??(dealerId&&envelope.identity.lead_id?'https://www.autopulse.ai/booking/'+dealerId+'/'+envelope.identity.lead_id:null);
envelope.context.dealer={...upstream,id:dealerId??upstream.id??null,bot_name:d.ai_bot_name??upstream.bot_name??null,store_name:d.store_name??d.dealership_name??upstream.store_name??null,store_phone:d.alternative_contact_number??d.store_phone??upstream.store_phone??incomingPhone,sms_conversion_phone:configuredPhone??upstream.sms_conversion_phone??upstream.store_phone??incomingPhone,store_address:configuredAddress??upstream.store_address??null,timezone:d.time_zone??d.timezone??upstream.timezone??null,store_website:d.store_website??d.website??upstream.store_website??null,manager_name:d.general_manager??d.manager_name??upstream.manager_name??null,trade_url:d.trade_in_appraisal_url??upstream.trade_url??null,finance_url:d.credit_finance_application_url??upstream.finance_url??null,booking_url:bookingUrl,store_hours:storeHours,store_hours_text:storeHoursText,store_hours_status:storeHoursStatus};
resolution.dealer_configuration_match_count=dealer?1:0;
resolution.dealer_configuration_source=dealer?'DATABASE':dealerId?'UPSTREAM_FALLBACK':'UPSTREAM_ONLY';
resolution.dealer_configuration_phone_validated=!!dealer&&!!configuredNormalized&&!!incomingNormalized&&configuredNormalized===incomingNormalized;
envelope.context.current_time={iso:new Date().toISOString(),timezone:envelope.context.dealer.timezone};
return [{json:envelope}];

const envelope=JSON.parse(JSON.stringify($node['Structure Dealer Context'].json));
const truthy=v=>v===true||v===1||v==='1'||String(v).toLowerCase()==='true';
const validMessageId=v=>typeof v==='string'?v.trim():'';
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const timeOf=r=>{const value=r.timestamp??r.date??r.created_at??r.createdAt;const ms=Date.parse(value);return Number.isFinite(ms)?ms:null;};
const rawCutoff=envelope.event.received_at;const cutoff=Date.parse(rawCutoff);const hasCutoff=!!rawCutoff&&Number.isFinite(cutoff);
const warnings=envelope.context.resolution.warnings??(envelope.context.resolution.warnings=[]);
if(!hasCutoff&&!warnings.includes('MISSING_OR_INVALID_EVENT_RECEIVED_AT_NO_HISTORY_CUTOFF'))warnings.push('MISSING_OR_INVALID_EVENT_RECEIVED_AT_NO_HISTORY_CUTOFF');
const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length&&(r._id||r.message_id));
const currentId=validMessageId(envelope.event.message_id);
const isCurrent=r=>{const historyId=validMessageId(r.message_id);return !!currentId&&!!historyId&&currentId===historyId;};
const historical=rows.filter(r=>!isCurrent(r)&&(!hasCutoff||(timeOf(r)!==null&&timeOf(r)<=cutoff)));
if(hasCutoff&&rows.some(r=>!isCurrent(r)&&timeOf(r)===null)&&!warnings.includes('HISTORY_RECORD_WITHOUT_VALID_TIMESTAMP_EXCLUDED'))warnings.push('HISTORY_RECORD_WITHOUT_VALID_TIMESTAMP_EXCLUDED');
historical.sort((a,b)=>{const byTime=(timeOf(a)??0)-(timeOf(b)??0);if(byTime)return byTime;return String(id(a._id)??validMessageId(a.message_id)).localeCompare(String(id(b._id)??validMessageId(b.message_id)));});
const allowed=historical.filter(r=>!truthy(r.internal_use)&&(r.use_replies_for_ai===undefined||r.use_replies_for_ai===null||truthy(r.use_replies_for_ai)));
const isNote=r=>truthy(r.is_note??r.isNote)||String(r.communication_type??'').toLowerCase()==='note';
envelope.context.sms_history=allowed.filter(r=>!isNote(r)&&String(r.communication_type??'sms').toLowerCase()!=='email').map(r=>({direction:['received','incoming'].includes(String(r.status).toLowerCase())?'inbound':'outbound',content:r.mail_content??r.message??r.content??r.api_response?.Response??null,status:r.status??null,timestamp:r.timestamp??r.date??r.created_at??r.createdAt??null,message_id:validMessageId(r.message_id)||null})).filter(r=>r.content);
envelope.context.lead_notes=allowed.filter(isNote).map(r=>({text:r.note??r.note_content??r.noteText??r.mail_content??r.message??null,timestamp:r.timestamp??r.date??r.created_at??r.createdAt??null})).filter(r=>r.text);
return [{json:envelope}];

