envelope.context.email_history=historical.map(r=>({direction:['received','incoming'].includes(String(r.status).toLowerCase())?'inbound':'outbound',content:r.mail_content??r.message??r.content??r.api_response?.Response??null,status:r.status??null,timestamp:r.timestamp??r.date??r.created_at??r.createdAt??null,message_id:validMessageId(r.message_id)||null})).filter(r=>r.content);
