const envelope=$node['Structure Email History'].json;
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const timeOf=r=>{const value=r.delivered_at??r.sent_at??r.createdAt;const ms=Date.parse(value);return Number.isFinite(ms)?ms:null;};
