memberships.sort((a,b)=>{const byTime=(timeOf(b)??0)-(timeOf(a)??0);if(byTime)return byTime;return String(id(a._id)??id(a.campaign_id)??'').localeCompare(String(id(b._id)??id(b.campaign_id)??''));});
const ids=[...new Set(memberships.map(r=>id(r.campaign_id)).filter(Boolean))];
return [{json:{dealer_id:envelope.identity.dealer_id||'__UNRESOLVED__',campaign_ids:ids,campaign_object_ids:ids.map(value=>({$oid:value}))}}];

